import{_ as r}from"./_plugin-vue_export-helper-DlAUqK2U.js";import{M as s,ar as t,aG as a,bK as l,L as n}from"./index-DWGrBUt2.js";const o={},i={class:"chapter-content"};function h(c,e){return n(),s("div",i,[...e[0]||(e[0]=[t("h2",{id:"今日主题"},"10 月 2 日 · 从海边出发，向新疆飞去",-1),t("p",null,[t("strong",null,"HB862：18:45 香港 → 次日 01:15 乌鲁木齐"),a("（官网计划，以客票和当日通知为准）。这一晚从香港飞向乌鲁木齐，抵达后先安顿好睡眠。香港 "),t("strong",null,"T2、7 楼 Q 行段"),a("值机；落地后直接去维斯顿休息，次日下午再到奎屯取车。")],-1),t("h2",{id:"关键时间轴"},"当天时间表",-1),t("div",{class:"table-scroll table-scroll--wide",tabindex:"0",role:"region","aria-label":"Day0 时间轴"},[t("table",null,[t("thead",null,[t("tr",null,[t("th",{scope:"col"},"时间"),t("th",{scope:"col"},"安排"),t("th",{scope:"col"},"注意")])]),t("tbody",null,[t("tr",null,[t("th",{scope:"row"},"12:00—13:00"),t("td",{"data-th":"安排"},"深圳吃午餐，13:15 动身赴口岸。"),t("td",{"data-th":"注意"},"证件、签注、四箱及随身包带齐。")]),t("tr",null,[t("th",{scope:"row"},[t("strong",null,"14:30—16:30")]),t("td",{"data-th":"安排"},"深圳湾集合，15:00 起过关；争取 15:20 上车、15:30 前发车，16:30 前到香港 T2 托运。"),t("td",{"data-th":"注意"},"过关后现场找大尾箱的士，无合适车立即叫即时单；排队拥挤就到齐提前过关。")]),t("tr",null,[t("th",{scope:"row"},"16:30—17:40"),t("td",{"data-th":"安排"},"T2 值机托运 → 安检出境 → 乘 APM 到 T1 登机区。"),t("td",{"data-th":"注意"},"常规柜台 17:45 截止；先办好手续，有余量再补餐。")]),t("tr",null,[t("th",{scope:"row"},[t("strong",null,"17:40")]),t("td",{"data-th":"安排"},"到实际登机口等候。"),t("td",{"data-th":"注意"},"常规登机口 18:30 截止；以当日通知为准。")]),t("tr",null,[t("th",{scope:"row"},[t("strong",null,"18:45")]),t("td",{"data-th":"安排"},"HB862 起飞。"),t("td",{"data-th":"注意"},"计划次日 01:15 抵达。")]),t("tr",null,[t("th",{scope:"row"},"次日 01:15—02:20"),t("td",{"data-th":"安排"},"入境、取行李，打车约 19 km / 25—35 min 到维斯顿。"),t("td",{"data-th":"注意"},"按北航站区指引上车；选可容纳四人四箱的大车。")]),t("tr",null,[t("th",{scope:"row"},"02:20—02:45"),t("td",{"data-th":"安排"},"入住、洗漱、充电，争取熄灯。"),t("td",{"data-th":"注意"},"排队可能顺延；次日计划 11:00 起床、12:30 火车。")])])])],-1),l('<h2 id="路线与停车">四人、四个 24 寸箱，过关后同乘一辆车</h2><h3 id="跨境衔接深圳-香港机场">先看现场大车，没有就即时叫车</h3><p><strong>不提前预约，过关后现场叫车。</strong>一辆车须同时容纳四人、四个 24 寸箱及随身包。星群 <strong>PRIME / MPT</strong>、大黄蜂 <strong>XL</strong> 有对应的大行李容量；普通轿车型不预设能装下，先让司机确认。</p><ol><li><strong>出关到的士站：</strong>完成香港入境后，按“公共运输交汇处／的士”指示去港方红／绿的士站，向现场人员说：<strong>“四位乘客、四个 24 寸行李箱，要一辆大尾箱的士去香港机场 T2。”</strong>按现场安排候车，是否能另候大车听管理人员指引。</li><li><strong>有合适车就直接装箱：</strong>四箱和随身包都放妥、尾门可关、四人座位安全带可用后出发。可以询问星群 MPT／PRIME、大黄蜂 XL 等大空间车型，不必等某个品牌。</li><li><strong>没有大车／候车时间不明就即时叫：</strong>用 <a href="https://syncab.com.hk/sc/booking/" target="_blank" rel="noreferrer">SynCab App／官网</a>选现在用车，或拨 <a href="tel:+85237006500">+852 3700 6500</a>，指定 PRIME／MPT，报四人四个 24 寸箱及随身包，先确认装载、到车时间和费用。也可拨大黄蜂 <a href="tel:+85251218888">+852 5121 8888</a>询问能否即时派 XL；只保留一个已确认的有效订单。</li><li><strong>即时派车按定位接：</strong>收到车牌和司机联系后，按其指引去港方<strong>车队专属停靠处</strong>（旅游巴士上客区部分范围）。这里供已匹配订单接载，不能把停着的车当作随到随上的空车。</li><li><strong>直达机场：</strong>报“T2 Departures／二号客运大楼离境层”，下车清点四箱，到 7 楼 Q 行段托运。</li></ol><div class="callout is-note"><strong>现场即时叫车话术</strong><p>“我们已经过关，在深圳湾港方口岸。4 人、4 个 24 寸箱，另有【随身包数量】，现在去香港机场 T2。请派一辆能全部装下的大尾箱的士，告知车牌、接载位置、到车时间和费用。”</p></div><p><strong>叫车时间提醒：</strong>争取 15:20 上车，15:25 仍未匹配到车就电话核调度、继续按现场指引找合适大车；15:30 未发车或导航到楼超过 16:30，立即联系航司，确认托运截止与迟到处理方式。道路段预留 45—60 min，找车装箱另计；国庆车源和排队情况可能使抵达时间延后。</p><p><strong>车费：</strong>直接在的士站乘车按表及规定附加费结算，四箱普通行李费共 HK$24；即时车队订单按页面／客服确认的计费方式，先问清行李、通行及叫车费是否已含。去程暂留 <strong>HK$500</strong> 为规划额度，备港币现金，返程另计。</p><details><summary>现场叫车的依据与待确认事项</summary><p><a href="https://www.td.gov.hk/tc/transport_in_hong_kong/land_based_cross_boundary_transport/access_to_shenzhen_bay_port/index_t.html" target="_blank" rel="noreferrer">运输署</a>确认港方有红／绿的士服务及车队专属接载区。<a href="https://syncab.com.hk/sc/services/syncab-taxi-services/" target="_blank" rel="noreferrer">星群</a>列明 PRIME 四人＋八件大型行李、MPT 四人／八件行李；<a href="https://h5.taxi.bigbee-hk.com/" target="_blank" rel="noreferrer">大黄蜂</a>官网列六人＋八件大行李。<a href="https://syncab.com.hk/en/services/frequently-asked-questions/" target="_blank" rel="noreferrer">星群 FAQ</a>明确支持即时调配附近车，较偏远地点可能更久。容量支持本次选车，实际箱体外尺寸及随身包由司机确认；没有 10-02 口岸实时车型库存，不能承诺立即有车。即时叫车会生成订单，无需提前约定接载时刻。</p></details><h2 id="餐饮住宿">落地与入住</h2><h3 id="凌晨落地打车">北航站区 → 维斯顿</h3><p><strong>维斯顿国际酒店（乌鲁木齐站北广场店）</strong>，高铁北三路 299 号，¥490 两间已订。务必保留<strong>10 月 2 日入住、3 日退房</strong>的订单并确认凌晨保房。落地取行李后直达；出租车预计排队超过 30 min 就比较网约车，在指定上客点汇合。</p><h3 id="今日吃什么">餐食与休息</h3><p>集合前吃一顿热饭；不安排机场闲逛与免税购物，到登机口后有余量再补餐，来不及就吃备好的零食。凌晨抵达，把入住、洗漱办妥便好好睡觉。若严重缺觉，重新评估次日驾驶安排；12:30 火车仍须按时搭乘。</p><h2 id="出发前核验">出发前勾选</h2><ul><li><label class="task task-live"><input type="checkbox" data-check-index="0"> <span>HB862 客票、PNR、值机托运截止及行李额度已核并离线保存</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="1"> <span>已保存现场叫车入口与电话、四箱外尺寸和随身包数量；香港流量与付款可用</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="2"> <span>维斯顿按 10 月 2 日房晚预订，凌晨保房已确认</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="3"> <span>次日 12:30—14:33 乌鲁木齐→奎屯火车电子票已保存</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="4"> <span>证件、订单、紧急联系人、香港流量与语音齐备</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="5"> <span>托运行李已称重；充电宝每人最多两个、核 Wh，备用电池随身绝缘；充电宝不放头顶行李架，机上不使用或充电</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="6"> <span>午餐已吃，水杯、零食、保暖外套随手可取</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="7"> <span>落地按现场指引选可容纳四人四箱的大车，直达维斯顿</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="8"> <span>入住后洗漱充电；次日按实际睡眠评估状态</span></label></li></ul><details><summary>官方依据（9 月 29—30 日复核）</summary><p><a href="https://www.greaterbay-airlines.com/hk/zh_HK/manage/before-your-flight/airport-information.html" target="_blank" rel="noreferrer">T2 值机与截止</a> · <a href="https://www.greaterbay-airlines.com/hk/zh_HK/book/flying-with-us/flight-schedule.html" target="_blank" rel="noreferrer">HB862 时刻表</a> · <a href="https://www.hongkongairport.com/en/media-centre/press-release/2026/pr_1868" target="_blank" rel="noreferrer">T2 至 T1 登机流程</a> · <a href="https://www.greaterbay-airlines.com/hk/zh_HK/manage/our-services/baggage.html" target="_blank" rel="noreferrer">行李与电池规则</a> · <a href="https://syncab.com.hk/sc/services/syncab-taxi-services/" target="_blank" rel="noreferrer">星群车型容量</a> · <a href="https://www.td.gov.hk/tc/transport_in_hong_kong/land_based_cross_boundary_transport/access_to_shenzhen_bay_port/index_t.html" target="_blank" rel="noreferrer">港方接载安排</a> · <a href="https://www.td.gov.hk/filemanager/tc/content_5241/List_of_Fleet_Taxi_Stopping_Places_TC.pdf" target="_blank" rel="noreferrer">专属停靠处</a> · <a href="https://www.td.gov.hk/filemanager/tc/content_276/TaxiFareTable20260510.pdf" target="_blank" rel="noreferrer">普通的士收费表</a>。派车、路况及当日航班仍按实际通知。</p></details>',16)])])}const g=r(o,[["render",h]]);export{g as default};
